<?php
/**
 * Clean-up of files left behind by older, non-WordPress.org builds.
 *
 * Builds before 1.2.0 could install an optional "early loader" file in
 * wp-content/mu-plugins. This version never writes that file. It only removes
 * it, and only when the file is recognisably ours.
 *
 * @package BotControl
 */

defined( 'ABSPATH' ) || exit;

/**
 * Legacy clean-up.
 */
final class Bot_Control_Legacy {

	const LOADER = 'bot-control-early-loader.php';

	/**
	 * Remove the legacy mu-plugin early loader if it exists and was generated by Bot Control.
	 *
	 * @return bool True when a file was removed.
	 */
	public static function remove_early_loader() {
		if ( ! defined( 'WPMU_PLUGIN_DIR' ) ) {
			return false;
		}
		$path = trailingslashit( WPMU_PLUGIN_DIR ) . self::LOADER;
		if ( ! is_file( $path ) || ! self::is_ours( $path ) ) {
			return false;
		}
		wp_delete_file( $path );
		return ! file_exists( $path );
	}

	/**
	 * Does the file carry the header and guard constant that only our generator wrote?
	 *
	 * @param string $path File path.
	 * @return bool
	 */
	private static function is_ours( $path ) {
		$head = get_file_data(
			$path,
			array(
				'name'   => 'Plugin Name',
				'author' => 'Author',
			)
		);
		if ( 'Bot Control – Early Loader' !== $head['name'] || 'Eli Shvarzman' !== $head['author'] ) {
			return false;
		}
		$contents = (string) file_get_contents( $path, false, null, 0, 8192 ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents -- Reading a small local file.
		return false !== strpos( $contents, "define( 'BOTCTL_EARLY_LOADED', true );" );
	}
}
